import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import {
  Container,
  Typography,
  Grid,
  Paper,
  Box,
  Chip,
  Divider,
  Card,
  CardContent,
  CardMedia,
} from '@mui/material';

import DetailHeaderNavi from './components/Nav/detailpageheader';
import {LineChart,Line,XAxis,YAxis,CartesianGrid,Tooltip,Legend,ResponsiveContainer} from 'recharts';


import Footer from "./components/Footer/footer";

type RankingRow = {
  issue_label: string;
  title: string;
  rank_num: number;
};


interface Work {
  id: number;
  work_id: number;
  title: string;
  title_kana: string;
  title_eng: string;
  author: string;
  serialization_start_date: string;
  end_flg: boolean;
  story: string;
  genre: string;
  created_at: string;
  updated_at: string;
  peak_rank: number;
  status: string;
  image_url: string;
  official_url: string;
};

interface Volume {
  volume: number;
  releaseDate: string;
  coverimage: string;
  price: number;
  isbn: string;
  description: string;
  pages: number;
}

interface RankingData {
  title: string;
  [key: string]: string | number;
}



const DetailPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [mangaDetail, setMangaDetail] = useState<Work | null>(null);
  const [volumes, setVolumes] = useState<Volume[]>([]);
  const [rankingData, setRankingData] = useState<RankingData[]>([]);
  const [loading, setLoading] = useState(true);
  const title = searchParams.get('title');

  useEffect(() => {
    const fetchData = async () => {
      try {
        // 漫画詳細の取得
        if (!title) return;
        const detailResponse = await fetch(`http://localhost:8080/work/${encodeURIComponent(title)}`);
        const detailData = await detailResponse.json();
        //let manga = detailData.manga.find((m: MangaDetail) => m.title === title);

        if (!mangaDetail?.title) {
            // タイトルが存在することを確認
            if (!title) {
              console.error('Title is empty or null');
              return;
            }
        }

       //console.log(detailData);

        setMangaDetail(detailData || null);

        // ランキングデータの取得
        fetch("http://localhost:8080/ranking")
        .then((response) => response.json())
        .then((rows: RankingRow[]) => {
          // =========================================
          // ① issueごとにまとめて「横持ち」形式へ変換
          // =========================================
          const grouped: { [issue: string]: any } = {};

          rows.forEach((row) => {
          if (!grouped[row.issue_label]) {
            grouped[row.issue_label] = {
              title: row.issue_label,
            };
          }

          grouped[row.issue_label][row.title] = row.rank_num;
          });

          const parsedData = Object.values(grouped);
          //setData(parsedData);
          setRankingData(parsedData);
        })

      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }

    }; // fetchData

    fetchData();
  }, [title]);


  useEffect(() => {
    const fetchVolumeData = async () => {
      if (!mangaDetail) return;

      try {
        const res = await fetch(
          `http://localhost:8080/volumes?work_id=${mangaDetail.work_id}`
        );

        if (!res.ok) {
          throw new Error("Failed to fetch volumes");
        }

        const data: Volume[] = await res.json();
        setVolumes(data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchVolumeData();
  }, [mangaDetail]);


  if (loading) {
    return (
      <Container>
        <Typography>Loading...</Typography>
      </Container>
    );
  }

  if (!mangaDetail) {
    return (
      <Container>
        <Typography color="error">漫画が見つかりませんでした。</Typography>
      </Container>
    );
  }


    return (
    <div className="bg-[#1a2332] text-white p-4 rounded-xl w-[320px] font-sans">
      {/* ヘッダー */}
      <div className="flex items-center justify-between mb-6">
        <span className="text-xl">＜</span>
        <h1 className="text-lg font-bold tracking-widest">{mangaDetail.title}</h1>
        <div className="w-4"></div>
      </div>

      {/* 統計カード */}
      <div className="grid grid-cols-4 gap-2 mb-6">
        <StatCard label="最新順位" value="1位" bgColor="bg-blue-600" />
        <StatCard label="平均順位" value="2.4位" sub="▲" bgColor="bg-teal-700" />
        <StatCard label="最高順位" value="1位" sub="↑" bgColor="bg-slate-700" />
        <StatCard label="最低順位" value="6位" sub="↓" bgColor="bg-slate-700" />
      </div>

      {/* 順位推移グラフ */}
      <div className="mb-6">
        <h3 className="text-sm mb-4 border-b border-gray-700 pb-1">順位推移</h3>
        <div className="h-40 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={rankingData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#334155" />
              <XAxis dataKey="name" hide />
              <YAxis reversed domain={[1, 10]} hide />
              <Line type="monotone" dataKey="rank" stroke="#60a5fa" strokeWidth={3} dot={{ r: 4, fill: '#fff' }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 号別リスト */}
      <div className="space-y-3">
        <RankingRow issue="第10号" rank="1位" />
        <RankingRow issue="第9号" rank="2位" />
        <RankingRow issue="第8号" rank="3位" />
      </div>

      {/* ボトムナビゲーション */}
      <div className="flex justify-around mt-8 pt-4 border-t border-gray-700 text-[10px] text-gray-400">
        <NavItem label="ホーム" active />
        <NavItem label="分析" />
        <NavItem label="作品" />
        <NavItem label="管理" />
      </div>
    </div>
  );


}


// サブコンポーネント
const StatCard = ({ label, value, sub, bgColor }: any) => (
  <div className={`${bgColor} p-2 rounded flex flex-col items-center justify-center`}>
    <span className="text-[8px] opacity-80 mb-1">{label}</span>
    <span className="text-sm font-bold">{value}</span>
    {sub && <span className="text-[8px]">{sub}</span>}
  </div>
);

const RankingRow = ({ issue, rank }: any) => (
  <div className="flex justify-between items-center text-sm border-b border-gray-800 pb-2">
    <span className="text-gray-400">{issue}</span>
    <span className="font-bold">{rank}</span>
  </div>
);

const NavItem = ({ label, active }: any) => (
  <div className={`flex flex-col items-center ${active ? 'text-blue-400' : ''}`}>
    <div className="w-5 h-5 bg-current opacity-20 rounded mb-1"></div>
    <span>{label}</span>
  </div>
);

export default DetailPage;
